/* Original Cyber 72 teaching scenarios. All examples are fictional and offline. */
window.C72Cases = (() => {
  const item=(id,title,story,options,lesson,anchor)=>({id,title,story,options:options.map((text,i)=>({text,safe:i===1})),lesson,anchor});
  return Object.freeze([
    item('sms',['Unknown SMS trap','ভুয়া টেক্সট মেসেজ'],
      ['An unknown number says I won ৳50,000 in a lottery! The message wants me to open a link to collect it. I never entered a lottery. What should I do?',
       'ভাই, অজানা নম্বর থেকে মেসেজ আসছে—আমি নাকি ৫০,০০০ টাকা লটারি জিতেছি! টাকা তুলতে একটা লিংকে চাপ দিতে বলছে। আমি তো কোনো লটারিতে নামই দিইনি। কী করব?'],
      [['Open the link and give my bKash number.','লিংকে চাপ দিয়ে আমার বিকাশ নম্বর দেব।'],['Leave the link alone; block and report the sender.','লিংকে চাপ দেব না; নম্বরটি ব্লক ও রিপোর্ট করব।'],['Forward the prize message to my friends.','পুরস্কারের মেসেজ বন্ধুদের পাঠিয়ে দেব।']],
      ['An unexpected prize can be bait for a payment or your personal information. Do not open its link or spread it. Report it through the messaging service.',
       'অপ্রত্যাশিত পুরস্কারের লোভ দেখিয়ে টাকা বা ব্যক্তিগত তথ্য চাইতে পারে। লিংকে চাপ দিও না, অন্যদেরও পাঠিও না। মেসেজের সেবায় রিপোর্ট করো।'],[-7,49]),
    item('messenger',['A friend needs money?','মেসেঞ্জারে টাকা চাওয়া'],
      ['My school senior messaged me on Messenger. He says he is in trouble and urgently needs ৳5,000 through bKash. Should I send it?',
       'মেসেঞ্জারে আমার স্কুলের বড় ভাইয়ের আইডি থেকে বলছে সে খুব বিপদে আছে। এখনই বিকাশে ৫,০০০ টাকা ধার চায়। আমি কি পাঠাব?'],
      [['Send it immediately because it is his account.','তার আইডি থেকে এসেছে বলে সঙ্গে সঙ্গে টাকা পাঠাব।'],['Call him using the number I already know, or speak in person first.','আগে থেকে জানা নম্বরে ফোন করে বা সামনাসামনি কথা বলে নিশ্চিত হব।'],['Send money to the other number in the message.','মেসেজে দেওয়া অন্য বিকাশ নম্বরে টাকা পাঠাব।']],
      ['An account can be copied or taken over. Verify the request through an independent contact you already trust, not a new number supplied in the message.',
       'আইডি নকল হতে পারে বা অন্যের দখলে যেতে পারে। মেসেজে দেওয়া নতুন নম্বরে নয়, আগে থেকে জানা নম্বরে যোগাযোগ করে যাচাই করো।'],[-9,25]),
    item('loan',['The five-minute loan','পাঁচ মিনিটের লোন'],
      ['A WhatsApp link promises a ৳20,000 loan in five minutes, without documents. The app wants access to my photos and contacts. Should I install it?',
       'হোয়াটসঅ্যাপে একটা লিংক পেলাম—কাগজ ছাড়াই পাঁচ মিনিটে ২০,০০০ টাকা লোন! অ্যাপটি ছবি আর কন্টাক্টের অনুমতিও চাইছে। নামাব নাকি?'],
      [['Install it and upload my personal details.','অ্যাপ নামিয়ে সব ব্যক্তিগত তথ্য দিয়ে দেব।'],['Avoid the unknown app and check a verified bank or lender directly.','অজানা অ্যাপ এড়িয়ে যাচাই করা ব্যাংক বা ঋণদাতার সঙ্গে সরাসরি কথা বলব।'],['Give the app my bank PIN to get the loan.','লোন পেতে অ্যাপটিতে ব্যাংকের পিন দেব।']],
      ['Unverified loan apps can misuse contacts, photos and identity details. Check the lender, terms and permissions independently. Never share a banking PIN to obtain a loan.',
       'অযাচাইকৃত লোন অ্যাপ কন্টাক্ট, ছবি ও পরিচয়ের তথ্যের অপব্যবহার করতে পারে। ঋণদাতা, শর্ত ও অনুমতি যাচাই করো। লোনের জন্য ব্যাংকের পিন কাউকে দিও না।'],[20,3]),
    item('pin',['Keep your PIN private','বিকাশ–নগদ পিন ফাঁদ'],
      ['A caller claims to be from bKash. He says my account will be blocked unless I tell him my OTP and PIN right now!',
       'একজন ফোন করে বলল সে বিকাশ অফিস থেকে বলছে। এখনই ওটিপি আর পিন না বললে নাকি আমার অ্যাকাউন্ট ব্লক হবে!'],
      [['Read out the PIN and OTP to save the account.','অ্যাকাউন্ট বাঁচাতে পিন আর ওটিপি বলে দেব।'],['Share neither; hang up and verify through the official service.','কিছুই দেব না; ফোন কেটে অফিসিয়াল সেবায় যাচাই করব।'],['Give half the PIN and share the rest later.','অর্ধেক পিন এখন, বাকিটা পরে বলব।']],
      ['A caller’s job title is not proof. bKash says never to share your PIN or verification codes. Contact the provider through its official app or independently verified support channel.',
       'অফিসের পরিচয় দিলেই বিশ্বাস নয়। বিকাশ পিন বা ভেরিফিকেশন কোড কাউকে না দিতে বলে। অফিসিয়াল অ্যাপ বা নিজে যাচাই করা সহায়তা মাধ্যমে যোগাযোগ করো।'],[7,27]),
    item('apk',['Free diamonds, hidden cost','ফ্রি ডায়মন্ডের এপিকে'],
      ['A YouTube video promises free Free Fire diamonds. It tells me to install an APK from a random site and allow every permission. Is it worth a try?',
       'ইউটিউব ভিডিওতে ফ্রি ফায়ার ডায়মন্ড ফ্রি দেওয়ার কথা বলছে। অচেনা সাইটের APK নামিয়ে সব অনুমতি দিতে হবে। চেষ্টা করব?'],
      [['Install it because the diamonds are free.','ফ্রি ডায়মন্ডের জন্য ইনস্টল করব।'],['Avoid the unknown APK; use the game’s official offers and trusted store.','অজানা APK এড়িয়ে গেমের অফিসিয়াল অফার ও বিশ্বস্ত স্টোর ব্যবহার করব।'],['Open the file and allow all permissions.','ফাইল খুলে সব পারমিশন Allow করব।']],
      ['A modified game or reward app may contain malware. Check the publisher and source, keep device protections on, and do not grant permissions unrelated to an app’s purpose.',
       'বদলানো গেম বা পুরস্কারের অ্যাপে ক্ষতিকর সফটওয়্যার থাকতে পারে। প্রকাশক ও উৎস যাচাই করো, ফোনের সুরক্ষা চালু রাখো, অপ্রয়োজনীয় অনুমতি দিও না।'],[-60,23]),
    item('marketplace',['The too-cheap iPhone','অবিশ্বাস্য দামে আইফোন'],
      ['A Marketplace seller offers an iPhone 15 Pro for ৳10,000. First I must send ৳2,000 as a booking payment. The seller is rushing me.',
       'মার্কেটপ্লেসে আইফোন ১৫ প্রো মাত্র ১০,০০০ টাকা! আগে ২,০০০ টাকা বুকিং মানি বিকাশ করতে হবে। বিক্রেতা খুব তাড়া দিচ্ছে।'],
      [['Pay the booking fee before someone else buys it.','অন্য কেউ কেনার আগে বুকিং মানি দেব।'],['Do not advance money; verify the seller and inspect safely before paying.','অগ্রিম দেব না; বিক্রেতা যাচাই করে নিরাপদে পণ্য দেখে মূল্য দেব।'],['Send the entire amount to reserve the phone.','ফোন রাখতে পুরো টাকা পাঠিয়ে দেব।']],
      ['Avoid advance payments to an unverified seller. Use buyer protection and, for local meetings, a public place with a trusted adult. Cash on delivery alone does not prove the item is genuine; check inspection rules.',
       'অযাচাইকৃত বিক্রেতাকে অগ্রিম দিও না। ক্রেতার সুরক্ষা আছে এমন পদ্ধতি বেছে নাও। দেখা করলে বিশ্বস্ত বড় কাউকে নিয়ে জনসমাগমে যাও। ক্যাশ অন ডেলিভারি মানেই আসল পণ্য নয়—পরীক্ষার সুযোগ আছে কি না দেখো।'],[-89,53]),
    item('job',['Pay to get a job?','চাকরির আগে টাকা?'],
      ['An online job promises ৳3,000 a day for liking YouTube videos from home. They want a ৳500 joining fee before I can begin.',
       'ঘরে বসে ইউটিউবে লাইক দিয়ে প্রতিদিন ৩,০০০ টাকা আয়ের চাকরি! শুরু করার আগে ৫০০ টাকা জয়েনিং ফি দিতে বলছে।'],
      [['Pay the fee to secure this easy income.','সহজ আয়ের সুযোগ নিতে ফি দেব।'],['Reject the pay-to-work offer and verify the employer independently.','কাজ পেতে টাকা দেওয়ার অফার এড়িয়ে নিয়োগদাতা আলাদাভাবে যাচাই করব।'],['Pay ৳1,000 to unlock higher earnings.','বেশি আয়ের জন্য ১,০০০ টাকা দেব।']],
      ['Paying money to unlock work or withdraw supposed earnings is a strong task-scam warning. Do not send a joining payment. Check the employer through independent sources.',
       'কাজ খুলতে বা কথিত আয় তুলতে আগে টাকা চাওয়া টাস্ক স্ক্যামের বড় লক্ষণ। জয়েনিং টাকা পাঠিও না। আলাদা বিশ্বস্ত উৎসে নিয়োগদাতা যাচাই করো।'],[20,73]),
    item('shop',['A shop with no history','অচেনা অনলাইন শপ'],
      ['A new Facebook shop sells beautiful shoes at half price. There are no reviews or comments, only a bKash number. Should I order?',
       'নতুন ফেসবুক পেজে সুন্দর জুতো অর্ধেক দামে! কোনো রিভিউ বা কমেন্ট নেই, শুধু বিকাশ নম্বর। অর্ডার করব?'],
      [['Pay in full because the photos look convincing.','ছবি সুন্দর বলে পুরো টাকা দিয়ে দেব।'],['Check independent feedback, seller details, returns and payment protection first.','আগে স্বাধীন রিভিউ, বিক্রেতার পরিচয়, ফেরত নীতি ও পেমেন্টের সুরক্ষা যাচাই করব।'],['Send a photo of my NID to the page inbox.','পেজের ইনবক্সে আমার এনআইডির ছবি পাঠাব।']],
      ['Product photos and page reviews can be copied or faked. Look for independent history and clear seller and refund details. Do not send identity documents to an unverified shop.',
       'পণ্যের ছবি ও পেজের রিভিউ নকল হতে পারে। স্বাধীন ক্রেতার অভিজ্ঞতা, বিক্রেতা ও ফেরত দেওয়ার নিয়ম যাচাই করো। অচেনা শপকে পরিচয়পত্রের ছবি দিও না।'],[73,21]),
    item('phishing',['Look at the address','ঠিকানাটা ভালো করে দেখো'],
      ['This page looks like Facebook, but the address says facebookk-login-bd.invalid. It asks me to log in again. Should I enter my password?',
       'দেখতে ফেসবুকের মতো, কিন্তু ঠিকানায় facebookk-login-bd.invalid লেখা। আবার লগইন করতে বলছে। পাসওয়ার্ড দেব?'],
      [['Log in because the colours and logo look familiar.','রং আর লোগো চেনা বলে লগইন করব।'],['Close it; open the official app or type the known official address myself.','বন্ধ করব; অফিসিয়াল অ্যাপ খুলব বা পরিচিত আসল ঠিকানা নিজে লিখব।'],['Use this page to reset my password.','এই পেজেই পাসওয়ার্ড রিসেট করব।']],
      ['Read the whole domain, not just the brand name inside it. This is not Facebook’s domain. A padlock or a particular domain ending alone cannot prove safety. The .invalid address here is a harmless training example.',
       'শুধু ব্র্যান্ডের নাম নয়, পুরো ডোমেইন দেখো। এটি ফেসবুকের ডোমেইন নয়। তালা চিহ্ন বা ডোমেইনের শেষ অংশ একাই নিরাপত্তার প্রমাণ নয়। এখানে .invalid ঠিকানাটি শুধু নিরাপদ প্রশিক্ষণের উদাহরণ।'],[91,-58]),
    item('dhamaka',['The two-minute dhamaka','দুই মিনিটের ধামাকা'],
      ['“Dhamaka offer!” A shopping site claims a branded gear bicycle costs just ৳199. A timer says only two minutes remain and everyone is buying!',
       'শপিং সাইটে ধামাকা অফার—ব্র্যান্ডের গিয়ার সাইকেল মাত্র ১৯৯ টাকা! টাইমারে আর দুই মিনিট, আর বলছে সবাই কিনছে!'],
      [['Pay quickly before the timer runs out.','টাইমার শেষ হওয়ার আগে দ্রুত পেমেন্ট করব।'],['Pause; avoid the pressured offer and check the shop and real price independently.','থামব; চাপের অফার এড়িয়ে শপ ও আসল দাম আলাদাভাবে যাচাই করব।'],['Tell my friends to buy before checking it.','যাচাই না করেই বন্ধুদের দ্রুত কিনতে বলব।']],
      ['Extreme discounts and countdowns can pressure you into skipping checks. Take your time, compare the real price and verify the seller. Do not pay or share an offer just because it feels urgent.',
       'অস্বাভাবিক ছাড় আর কাউন্টডাউন যাচাই না করেই সিদ্ধান্ত নিতে চাপ দেয়। সময় নাও, আসল দাম মিলিয়ে বিক্রেতা যাচাই করো। তাড়া আছে বলে পেমেন্ট বা শেয়ার কোরো না।'],[0,-91])
  ]);
})();
